<?php
require __DIR__ . '/app/bootstrap.php';require_user();$user=current_user();
$q=$pdo->prepare('SELECT id,public_code,customer_name,total_amount,status,payment_status,created_at FROM orders WHERE user_id=? ORDER BY id DESC LIMIT 100');$q->execute([(int)$user['id']]);$orders=$q->fetchAll();
render_header('حساب کاربری'); ?>
<main class="container"><div class="page-title"><h1>حساب کاربری من</h1><p>خوش آمدید، <?=e($user['full_name'])?></p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('account.php'))?>">داشبورد حساب</a><a href="<?=e(site_url('products.php'))?>">ادامه خرید</a><form method="post" action="<?=e(site_url('logout.php'))?>"><?=csrf_field()?><button class="small-btn">خروج از حساب</button></form></aside><section class="admin-content"><div class="stats"><div class="stat"><span>نام و نام خانوادگی</span><strong style="font-size:17px"><?=e($user['full_name'])?></strong></div><div class="stat"><span>ایمیل</span><strong style="font-size:15px;overflow-wrap:anywhere"><?=e($user['email'])?></strong></div><div class="stat"><span>تعداد سفارش‌ها</span><strong><?=count($orders)?></strong></div></div><h2>سفارش‌های من</h2><?php if(!$orders): ?><div class="empty">هنوز سفارشی ثبت نکرده‌اید. <a href="<?=e(site_url('products.php'))?>" style="color:var(--gold)">مشاهده محصولات</a></div><?php else: ?><div class="table-wrap"><table class="table"><thead><tr><th>کد پیگیری</th><th>تاریخ</th><th>مبلغ</th><th>وضعیت</th><th>پرداخت</th><th>جزئیات</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e(substr($o['public_code'],0,8))?>…</td><td><?=e($o['created_at'])?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['status']==='pending'?'در انتظار بررسی':$o['status'])?></td><td><?=e($o['payment_status']==='unpaid'?'پرداخت نشده':$o['payment_status'])?></td><td><a style="color:var(--gold)" href="<?=e(site_url('order.php?code='.$o['public_code']))?>">مشاهده</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div></main><?php render_footer(); ?>